CREATE FUNCTION signal_report_summary(_ids uuid[]) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$SELECT jsonb_build_object('total',count(*),'unassigned',count(*) FILTER(WHERE assigned_to IS NULL),'accepted',count(*) FILTER(WHERE assigned_to IS NOT NULL AND status<>'waiting'),'waiting',count(*) FILTER(WHERE status='waiting'),'contacting',count(*) FILTER(WHERE status='contacting'),'consulting',count(*) FILTER(WHERE status='consulting'),'quoted',count(*) FILTER(WHERE status='quoted'),'deposit',count(*) FILTER(WHERE status='deposit'),'won',count(*) FILTER(WHERE status='won'),'lost',count(*) FILTER(WHERE status='lost'),'revenue',coalesce(sum(revenue) FILTER(WHERE status='won'),0),'closeRate',100.0*count(*) FILTER(WHERE status='won')/nullif(count(*),0),'overdue',0,'dueToday',0,'noNote',0) FROM opportunity_signals WHERE id=ANY(_ids)$$;
REVOKE ALL ON FUNCTION signal_report_summary(uuid[]) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION signal_report_summary(uuid[]) TO authenticated;
CREATE FUNCTION signal_sales_report(_filter jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH selected AS MATERIALIZED(SELECT * FROM signal_filtered(_filter)),unbounded AS MATERIALIZED(SELECT * FROM signal_filtered(_filter-'from'-'to'-'basis')),groups AS(SELECT 'source' kind,source key,array_agg(id) ids FROM selected GROUP BY source UNION ALL SELECT 'sale',assigned_to::text,array_agg(id) FROM selected WHERE assigned_to IS NOT NULL GROUP BY assigned_to UNION ALL SELECT 'product',p,array_agg(DISTINCT id) FROM selected CROSS JOIN LATERAL unnest(products) p GROUP BY p UNION ALL SELECT 'need',g,array_agg(DISTINCT id) FROM selected CROSS JOIN LATERAL unnest(CASE WHEN cardinality(need_groups)>0 THEN need_groups ELSE array_remove(ARRAY[need_group],NULL) END) g GROUP BY g UNION ALL SELECT 'potential',coalesce(potential,'unrated'),array_agg(id) FROM selected GROUP BY potential),trend_events AS(SELECT detected_on AS date_key,'created' kind FROM unbounded UNION ALL SELECT (closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,'won' FROM unbounded WHERE status='won'),trend AS(SELECT date_key,count(*) FILTER(WHERE kind='created') created,count(*) FILTER(WHERE kind='won') won FROM trend_events WHERE (coalesce(_filter->>'from','')='' OR date_key>=(_filter->>'from')::date) AND (coalesce(_filter->>'to','')='' OR date_key<=(_filter->>'to')::date) GROUP BY date_key),accepts AS(SELECT s.id,s.assigned_to,(SELECT max(e.created_at) FROM opportunity_signal_events e WHERE e.signal_id=s.id AND e.kind='assign' AND e.detail->>'to'=s.assigned_to::text) starts FROM selected s WHERE s.assigned_to IS NOT NULL),samples AS(SELECT a.*,(SELECT min(n.created_at) FROM opportunity_signal_notes n WHERE n.signal_id=a.id AND n.author_id=a.assigned_to AND n.status_from='waiting' AND n.created_at>=a.starts) accepted FROM accepts a),lost AS(SELECT CASE WHEN lost_reason LIKE 'Khác%' THEN 'Khác' ELSE coalesce(lost_reason,'Không rõ') END key,count(*) n FROM selected WHERE status='lost' GROUP BY key),stages AS(SELECT CASE WHEN status IS NULL OR status IN ('waiting','contacting') THEN 'intake' WHEN status IN ('consulting','quoted') THEN 'advice' WHEN status='lost' THEN 'ended' ELSE 'closing' END key,count(*) n FROM selected WHERE potential='high' GROUP BY key) SELECT jsonb_build_object('summary',signal_report_summary(coalesce((SELECT array_agg(id) FROM selected),'{}')),'groups',coalesce((SELECT jsonb_agg(jsonb_build_object('kind',kind,'key',key,'s',signal_report_summary(ids))) FROM groups),'[]'),'trend',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY date_key) FROM trend t),'[]'),'accepts',coalesce((SELECT jsonb_agg(to_jsonb(a)) FROM samples a),'[]'),'lost',coalesce((SELECT jsonb_agg(to_jsonb(l)) FROM lost l),'[]'),'stages',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM stages s),'[]'),'sales',coalesce((SELECT jsonb_agg(DISTINCT assigned_to) FILTER(WHERE assigned_to IS NOT NULL) FROM opportunity_signals),'[]'),'creators',coalesce((SELECT jsonb_agg(DISTINCT created_by) FROM opportunity_signals),'[]'))$$;
REVOKE ALL ON FUNCTION signal_sales_report(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION signal_sales_report(jsonb) TO authenticated;